import re


def slugify(s):
    s = s.lower()
    s = re.sub(r'[^a-z0-9]+', '-', s)
    return s.strip('-')

import unicodedata


def slugify(s):
    # Decompose unicode and strip combining marks so accented chars
    # map to their base letter (e.g. 'õ' -> 'o').
    s = unicodedata.normalize('NFD', s).lower()
    s = ''.join(c for c in s if not unicodedata.combining(c))

    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    return ''.join(out).strip('-')

import unicodedata

def slugify(s):
    s = unicodedata.normalize('NFKD', s).lower()
    # Remove combining marks so accented characters collapse to their ASCII base
    s = ''.join(ch for ch in s if unicodedata.category(ch) != 'Mn')
    out = []
    prev_non_alnum = False
    for ch in s:
        if ch.isalnum():
            out.append(ch)
            prev_non_alnum = False
        else:
            if not prev_non_alnum:
                out.append('-')
            prev_non_alnum = True
    if out and out[0] == '-':
        out = out[1:]
    if out and out[-1] == '-':
        out = out[:-1]
    return ''.join(out)
